function makeNodeComponent(nodeName) {
  const func = function (props) {
    const { variants, args, overrides } = React.useMemo(
      () =>
        deriveRenderOpts(props, {
          name: nodeName,
          descendantNames: PlasmicDescendants[nodeName],
          internalArgPropNames: PlasmicSearchLayout__ArgProps,
          internalVariantPropNames: PlasmicSearchLayout__VariantProps
        }),
      [props, nodeName]
    );
    return PlasmicSearchLayout__RenderFunc({
      variants,
      args,
      overrides,
      forNode: nodeName
    });
  };
  if (nodeName === "root") {
    func.displayName = "PlasmicSearchLayout";
  } else {
    func.displayName = `PlasmicSearchLayout.${nodeName}`;
  }
  return func;
}

